// ---------- ICONE ----------

// SVG inline da ICONS (js/icons.js). weight: 'regular' (interfaccia) | 'duotone' (alimenti).
function icon(name, { weight = 'regular', cls = '' } = {}) {
  const def = ICONS[name] || ICONS.basket;
  const c = `ico${cls ? ' ' + cls : ''}`;
  if (def.v === 256) {
    const tone = weight === 'duotone' ? def.tone.map((d) => `<path d="${d}" opacity=".2"/>`).join('') : '';
    const body = (weight === 'duotone' && def.toneFill ? def.toneFill : def.fill).map((d) => `<path d="${d}"/>`).join('');
    return `<svg class="${c}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${tone}${body}</svg>`;
  }
  const tone =
    weight === 'duotone' ? def.tone.map((d) => `<path d="${d}" fill="currentColor" stroke="none" opacity=".2"/>`).join('') : '';
  const body = def.stroke.map((d) => `<path d="${d}"/>`).join('');
  return `<svg class="${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${tone}${body}</svg>`;
}

function hydrateIcons(root = document) {
  root.querySelectorAll('i[data-icon]').forEach((i) => {
    const tpl = document.createElement('template');
    tpl.innerHTML = icon(i.dataset.icon, { cls: i.className });
    i.replaceWith(tpl.content.firstChild);
  });
}

// ---------- UTILITY ----------

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function haptic(ms = 8) {
  if (navigator.vibrate) navigator.vibrate(ms);
}

function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function plural(n, one, many) {
  return n === 1 ? `1 ${one}` : `${n} ${many}`;
}

function orderedCategories() {
  const pos = new Map(categoryOrder.map((id, i) => [id, i]));
  return CATEGORIES.slice().sort((a, b) => (pos.get(a.id) ?? 99) - (pos.get(b.id) ?? 99));
}

function categoryById(id) {
  return CATEGORIES.find((c) => c.id === id) || CATEGORIES[0];
}

let toastTimer = null;

function showToast(message, { actionLabel = null, onAction = null, duration = 3200 } = {}) {
  el.toastMsg.textContent = message;
  el.toastAction.classList.toggle('hidden', !actionLabel);
  el.toastAction.textContent = actionLabel || '';
  el.toastAction.onclick = actionLabel
    ? () => {
        hideToast();
        onAction();
      }
    : null;
  el.toast.classList.add('show');
  clearTimeout(toastTimer);
  if (duration) toastTimer = setTimeout(hideToast, actionLabel ? Math.max(duration, 5000) : duration);
}

function hideToast() {
  el.toast.classList.remove('show');
}

// ---------- DATI ----------

function activeLists() {
  return lists.filter((l) => !l.archived).sort((a, b) => b.createdAt - a.createdAt);
}

function archivedLists() {
  return lists.filter((l) => l.archived).sort((a, b) => (b.archivedAt || b.createdAt) - (a.archivedAt || a.createdAt));
}

function getList(id) {
  return lists.find((l) => l.id === id) || null;
}

function getSelectedList() {
  return getList(selectedListId);
}

function listProgress(list) {
  const total = list.items.length;
  const checked = list.items.filter((i) => i.checked).length;
  return { total, checked, pct: total === 0 ? 0 : Math.round((checked / total) * 100) };
}

function persistList(list) {
  if (list) saveList(list);
}

function rebuildFoodIndexes() {
  foodsById = new Map(foods.map((f) => [f.id, f]));
  foodsByCategory = new Map();
  for (const f of foods.slice().sort((a, b) => a.name.localeCompare(b.name, 'it'))) {
    if (!foodsByCategory.has(f.category)) foodsByCategory.set(f.category, []);
    foodsByCategory.get(f.category).push(f);
  }
}

function defaultListName() {
  const base = `Spesa del ${new Date().toLocaleDateString('it-IT', { day: 'numeric', month: 'long' })}`;
  const names = new Set(activeLists().map((l) => l.name));
  if (!names.has(base)) return base;
  let n = 2;
  while (names.has(`${base} (${n})`)) n++;
  return `${base} (${n})`;
}

async function createList({ name = defaultListName(), items = [] } = {}) {
  const saved = await saveList({ name, createdAt: Date.now(), archived: false, items });
  lists.push(saved);
  selectedListId = saved.id;
  return saved;
}

// Il catalogo ha sempre una lista di destinazione: se non ce n'è una, la crea.
async function ensureTargetList() {
  const current = getSelectedList();
  if (current && !current.archived) return current;
  const al = activeLists();
  if (al.length > 0) {
    selectedListId = al[0].id;
    return al[0];
  }
  return createList();
}

function toggleFoodInList(list, foodId) {
  const idx = list.items.findIndex((i) => i.foodId === foodId);
  if (idx >= 0) list.items.splice(idx, 1);
  else list.items.push({ foodId, checked: false });
  persistList(list);
  return idx < 0;
}

// Icone delle versioni precedenti (Lucide) → icone attuali.
async function migrateFoodIcons() {
  const seedByName = new Map(FOODS.map((f) => [normalizeName(f.name), f]));
  const updates = [];
  for (const food of foods) {
    if (ICONS[food.icon]) continue;
    const seed = seedByName.get(normalizeName(food.name));
    const guess = guessCategoryAndIcon(food.name);
    food.icon =
      (seed && seed.icon) ||
      (guess.category === food.category ? guess.icon : null) ||
      LEGACY_ICON_MAP[food.icon] ||
      categoryById(food.category).icon;
    updates.push(putFood(food));
  }
  await Promise.all(updates);
}

// Alimenti più comprati nelle liste archiviate (le più recenti pesano di più).
function frequentFoods(excludeIds, limit = 8) {
  const score = new Map();
  archivedLists().forEach((l, rank) => {
    const w = Math.pow(0.85, rank);
    for (const it of l.items) {
      if (foodsById.has(it.foodId)) score.set(it.foodId, (score.get(it.foodId) || 0) + w);
    }
  });
  return [...score.entries()]
    .filter(([id]) => !excludeIds.has(id))
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([id]) => foodsById.get(id));
}

// ---------- NAVIGAZIONE (router a hash) ----------

const VIEW_HASH = { lists: '#/liste', history: '#/storico', catalog: '#/catalogo', offers: '#/offerte' };
const VIEW_ORDER = { lists: 0, catalog: 1, offers: 2, history: 3, detail: 4 };

function parseHash(hash) {
  const m = hash.match(/^#\/lista\/(\d+)/);
  if (m) return { view: 'detail', listId: Number(m[1]) };
  if (hash.startsWith('#/storico')) return { view: 'history', listId: null };
  if (hash.startsWith('#/catalogo')) return { view: 'catalog', listId: null };
  if (hash.startsWith('#/offerte')) return { view: 'offers', listId: null };
  return { view: 'lists', listId: null };
}

function hashFor(view, listId) {
  return view === 'detail' ? `#/lista/${listId}` : VIEW_HASH[view];
}

// Le pagine aperte dall'app sono marcate `fromApp`: il pulsante Indietro dell'interfaccia
// torna alla pagina precedente solo se è dell'app, altrimenti va alle liste.
function navigate(view, { listId = null, replace = false } = {}) {
  // con sheet aperti si chiudono prima, così la cronologia resta coerente
  if (sheetStack.length) {
    closeAllSheets(() => navigate(view, { listId, replace }));
    return;
  }
  const hash = hashFor(view, listId);
  if (location.hash !== hash) {
    if (replace) history.replaceState({ ...(history.state || {}), sheet: undefined }, '', hash);
    else history.pushState({ fromApp: true, prev: location.hash }, '', hash);
  }
  applyRoute(parseHash(hash));
}

function goBack() {
  if (history.state && history.state.fromApp) history.back();
  else navigate('lists', { replace: true });
}

// Esce dal dettaglio (dopo archiviazione/eliminazione) senza lasciare voci doppie in cronologia.
function leaveDetail() {
  if (route.view !== 'detail') render();
  else if (history.state && history.state.fromApp && history.state.prev === VIEW_HASH.lists && !sheetStack.length) history.back();
  else navigate('lists', { replace: true });
}

function withTransition(direction, update) {
  if (!document.startViewTransition || reducedMotion.matches) {
    update();
    return;
  }
  document.documentElement.dataset.nav = direction;
  const t = document.startViewTransition(update);
  t.finished.finally(() => delete document.documentElement.dataset.nav);
}

function applyRoute(next) {
  if (next.view === 'detail') {
    const list = getList(next.listId);
    if (!list) {
      navigate('lists', { replace: true });
      return;
    }
    selectedListId = list.id;
  }
  const prev = route;
  if (prev.view === 'detail' && next.view !== 'detail') setShoppingMode(false);
  route = next;

  let direction = 'fade';
  if (next.view === 'detail' && prev.view !== 'detail') direction = 'forward';
  else if (prev.view === 'detail' && next.view !== 'detail') direction = 'back';
  else if (VIEW_ORDER[next.view] !== VIEW_ORDER[prev.view])
    direction = VIEW_ORDER[next.view] > VIEW_ORDER[prev.view] ? 'left' : 'right';

  const changed = prev.view !== next.view || prev.listId !== next.listId;
  const update = () => {
    render();
    if (changed) window.scrollTo(0, 0);
  };
  if (changed && document.body.classList.contains('ready')) withTransition(direction, update);
  else update();
}


// ---------- SHEET (bottom sheet / dialoghi) ----------

const sheetHandlers = {}; // id → { onClose }

function setBackgroundInert(on) {
  document.querySelectorAll('.app, .bottom-nav, #fab, #selectionPill').forEach((n) => (n.inert = on));
}

function openSheet(id, { onClose } = {}) {
  const sheet = $(`sheet-${id}`);
  if (!sheet || sheetStack.includes(id)) return;
  if (sheetStack.length) $(`sheet-${sheetStack[sheetStack.length - 1]}`).inert = true;
  setBackgroundInert(true);
  sheetHandlers[id] = { onClose, returnFocus: document.activeElement };
  sheetStack.push(id);
  sheet.hidden = false;
  requestAnimationFrame(() => sheet.classList.add('open'));
  document.body.classList.add('has-sheet');
  history.pushState({ ...(history.state || {}), fromApp: true, sheet: id }, '');
  const focusTarget = sheet.querySelector('[autofocus], input:not([type=file]), .menu-item, .btn-primary');
  if (focusTarget && !(focusTarget.tagName === 'INPUT' && matchMedia('(pointer: coarse)').matches && id !== 'food')) {
    setTimeout(() => focusTarget.focus({ preventScroll: true }), 60);
  }
}

// Ogni sheet aperto ha una voce nella cronologia, così il tasto Indietro lo chiude.
// Chiudendo da interfaccia si torna indietro di N voci; `then` parte dopo il popstate,
// così eventuali navigazioni o nuovi sheet non si sovrappongono alla cronologia.
let pendingPop = null;

function closeSheets(count = 1, then = null) {
  const n = Math.min(count, sheetStack.length);
  for (let i = 0; i < n; i++) closeTopSheet({ fromHistory: true });
  if (n > 0) {
    pendingPop = { then };
    history.go(-n);
  } else if (then) {
    then();
  }
}

function closeAllSheets(then = null) {
  closeSheets(sheetStack.length, then);
}

function closeTopSheet({ fromHistory = false } = {}) {
  if (!fromHistory) {
    closeSheets(1);
    return;
  }
  const id = sheetStack.pop();
  if (!id) return;
  const sheet = $(`sheet-${id}`);
  sheet.classList.remove('open');
  const done = () => {
    if (!sheet.classList.contains('open')) sheet.hidden = true;
  };
  if (reducedMotion.matches) done();
  else setTimeout(done, 240);
  if (sheetStack.length === 0) {
    document.body.classList.remove('has-sheet');
    setBackgroundInert(false);
  } else {
    $(`sheet-${sheetStack[sheetStack.length - 1]}`).inert = false;
  }
  const h = sheetHandlers[id] || {};
  delete sheetHandlers[id];
  if (h.onClose) h.onClose();
  if (h.returnFocus && document.contains(h.returnFocus)) h.returnFocus.focus({ preventScroll: true });
}

window.addEventListener('popstate', () => {
  if (pendingPop) {
    const { then } = pendingPop;
    pendingPop = null;
    if (then) then();
    return;
  }
  if (sheetStack.length) {
    closeTopSheet({ fromHistory: true });
    return;
  }
  // Indietro/Avanti del browser fra pagine dell'app (o hash scritto a mano)
  applyRoute(parseHash(location.hash));
});

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && sheetStack.length) {
    e.preventDefault();
    closeTopSheet();
  }
});

// Click sullo sfondo dello sheet = chiudi.
document.querySelectorAll('.sheet').forEach((sheet) => {
  sheet.addEventListener('click', (e) => {
    if (e.target === sheet) closeTopSheet();
  });
});

// Trascinare in basso la maniglia chiude lo sheet (mobile).
document.querySelectorAll('.sheet-grabber').forEach((grabber) => {
  const panel = grabber.closest('.sheet-panel');
  let startY = null;
  grabber.addEventListener('pointerdown', (e) => {
    startY = e.clientY;
    grabber.setPointerCapture(e.pointerId);
    panel.style.transition = 'none';
  });
  grabber.addEventListener('pointermove', (e) => {
    if (startY === null) return;
    panel.style.transform = `translateY(${Math.max(0, e.clientY - startY)}px)`;
  });
  const end = (e) => {
    if (startY === null) return;
    const dy = e.clientY - startY;
    startY = null;
    panel.style.transition = '';
    panel.style.transform = '';
    if (dy > 90) closeTopSheet();
  };
  grabber.addEventListener('pointerup', end);
  grabber.addEventListener('pointercancel', end);
});

function confirmAction(message, onConfirm, { confirmLabel = 'Elimina' } = {}) {
  el.confirmMessage.textContent = message;
  el.confirmOkBtn.textContent = confirmLabel;
  confirmCallback = onConfirm;
  // la conferma sostituisce l'eventuale menu da cui è partita
  closeAllSheets(() => openSheet('confirm'));
}

let confirmCallback = null;

// ---------- RENDERING ----------

function render() {
  renderChrome();
  if (route.view === 'lists') renderLists();
  else if (route.view === 'history') renderHistory();
  else if (route.view === 'catalog') renderCatalog();
  else if (route.view === 'offers') renderOffers();
  else if (route.view === 'detail') renderDetail();
  if (sheetStack.includes('quickAdd')) renderQuickAdd();
}

function renderChrome() {
  const tab = route.view === 'detail' ? 'lists' : route.view;
  document.querySelectorAll('[data-action="go-tab"]').forEach((btn) => {
    const active = btn.dataset.view === tab;
    btn.classList.toggle('active', active);
    if (active) btn.setAttribute('aria-current', 'page');
    else btn.removeAttribute('aria-current');
  });
  for (const [name, node] of Object.entries(el.views)) node.classList.toggle('hidden', name !== route.view);
  document.body.dataset.view = route.view;

  // FAB contestuale: nuova lista nelle liste/storico, nascosto altrove
  el.fab.classList.toggle('hidden', !(route.view === 'lists' || route.view === 'history'));

  const list = getSelectedList();
  const showPill = route.view === 'catalog' && list && !list.archived && list.items.length > 0;
  el.selectionPill.classList.toggle('hidden', !showPill);
  if (showPill) {
    el.selectionPill.innerHTML = `${icon('basket')}<span><strong>${list.items.length}</strong> in ${escapeHtml(list.name)}</span>${icon('caret-right')}`;
  }
}

function listPreviewIcons(list, max = 5) {
  return list.items
    .slice(0, max)
    .map((it) => {
      const food = foodsById.get(it.foodId);
      if (!food) return '';
      const color = categoryById(food.category).color;
      return `<span class="preview-icon" style="--cat:${color}" title="${escapeHtml(food.name)}">${icon(food.icon, { weight: 'duotone' })}</span>`;
    })
    .join('');
}

function renderLists() {
  const al = activeLists();
  el.noActiveLists.classList.toggle('hidden', al.length > 0);
  el.activeListsGrid.innerHTML = al
    .map((l) => {
      const { total, checked, pct } = listProgress(l);
      const meta =
        total === 0 ? 'Vuota' : checked === 0 ? plural(total, 'alimento', 'alimenti') : `${checked} di ${total} presi`;
      const extra = total > 5 ? `<span class="preview-more">+${total - 5}</span>` : '';
      return `
      <article class="list-card${total > 0 && checked === total ? ' is-done' : ''}" data-action="open-list" data-list-id="${l.id}" tabindex="0" role="link" aria-label="Apri ${escapeHtml(l.name)}">
        <h2 class="list-card-name">${escapeHtml(l.name)}</h2>
        <p class="list-card-meta">${meta}</p>
        <div class="list-card-preview">${listPreviewIcons(l)}${extra}</div>
        <div class="progress progress-thin" aria-hidden="true"><div class="progress-fill" style="width:${pct}%"></div></div>
      </article>`;
    })
    .join('');
}

function renderHistory() {
  const al = archivedLists();
  el.emptyHistory.classList.toggle('hidden', al.length > 0);
  el.historyItems.innerHTML = al
    .map((l) => {
      const date = new Date(l.archivedAt || l.createdAt).toLocaleDateString('it-IT', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
      });
      return `
      <article class="history-row">
        <div class="history-info">
          <h2 class="history-name">${escapeHtml(l.name)}</h2>
          <p class="history-meta">${date}, ${plural(l.items.length, 'alimento', 'alimenti')}</p>
          <div class="list-card-preview">${listPreviewIcons(l, 8)}</div>
        </div>
        <div class="history-actions">
          <button class="btn btn-primary btn-sm restore-btn" data-action="restore-list" data-list-id="${l.id}" title="Crea una nuova spesa con questi alimenti">${icon('arrow-counter-clockwise')}<span>Ripeti spesa</span></button>
          <button class="icon-btn" data-action="delete-archived" data-list-id="${l.id}" aria-label="Elimina ${escapeHtml(l.name)}" title="Elimina">${icon('trash')}</button>
        </div>
      </article>`;
    })
    .join('');
}

function renderTargetSelect() {
  const al = activeLists();
  if (al.length === 0) {
    el.targetListSelect.innerHTML = '<option value="">Nuova lista</option>';
    return;
  }
  if (!al.some((l) => l.id === selectedListId)) selectedListId = al[0].id;
  el.targetListSelect.innerHTML = al
    .map((l) => `<option value="${l.id}" ${l.id === selectedListId ? 'selected' : ''}>${escapeHtml(l.name)}</option>`)
    .join('');
}

function renderCatalog() {
  renderTargetSelect();
  const list = getSelectedList();
  renderFoodPicker(el.catalogPicker, {
    selectedIds: new Set(list && !list.archived ? list.items.map((i) => i.foodId) : []),
    query: catalogQuery,
    manage: true,
  });
}

function renderQuickAdd() {
  const list = getSelectedList();
  if (!list) return;
  el.quickAddSubtitle.textContent = `In ${list.name}`;
  el.quickAddCount.textContent =
    list.items.length === 0 ? 'Tocca un alimento per aggiungerlo' : `${plural(list.items.length, 'alimento', 'alimenti')} in lista`;
  renderFoodPicker(el.quickAddPicker, {
    selectedIds: new Set(list.items.map((i) => i.foodId)),
    query: quickAddQuery,
    manage: false,
  });
}

function foodChip(food, cat, selected, manage) {
  const edit =
    manage && food.custom
      ? `<button type="button" class="chip-edit" data-action="edit-food" data-food-id="${food.id}" aria-label="Modifica ${escapeHtml(food.name)}" title="Modifica">${icon('pencil-simple')}</button>`
      : '';
  return `
    <div class="chip${selected ? ' selected' : ''}" style="--cat:${cat.color}">
      <button type="button" class="chip-main" data-action="toggle-food" data-food-id="${food.id}" aria-pressed="${selected}">
        <span class="chip-icon">${icon(food.icon, { weight: 'duotone' })}<span class="chip-state">${icon('check')}</span></span>
        <span class="chip-name">${escapeHtml(food.name)}</span>
      </button>${edit}
    </div>`;
}

// Selettore di alimenti condiviso fra catalogo e aggiunta rapida.
function renderFoodPicker(container, { selectedIds, query, manage }) {
  const q = normalizeName(query || '');
  const cats = orderedCategories();
  let html = '';

  if (q) {
    const exact = foods.some((f) => normalizeName(f.name) === q);
    if (!exact) {
      const guess = guessCategoryAndIcon(query);
      const cat = categoryById(guess.category);
      html += `
        <button type="button" class="create-row" data-action="create-from-search" style="--cat:${cat.color}">
          <span class="chip-icon">${icon(guess.icon, { weight: 'duotone' })}</span>
          <span class="create-text">Aggiungi «${escapeHtml(capitalize(query.replace(/\s+/g, ' ').trim()))}»<small>Nuovo alimento in ${escapeHtml(cat.name)}</small></span>
          ${icon('plus', { cls: 'create-plus' })}
        </button>`;
    }
  } else {
    const frequent = frequentFoods(selectedIds);
    if (frequent.length > 0) {
      html += `
        <section class="picker-group picker-frequent">
          <h3 class="picker-heading">${icon('sparkle')}<span>Compri spesso</span></h3>
          <div class="chip-row">${frequent.map((f) => foodChip(f, categoryById(f.category), false, false)).join('')}</div>
        </section>`;
    }
    html += `<nav class="cat-jump" aria-label="Vai al reparto">${cats
      .filter((c) => (foodsByCategory.get(c.id) || []).length)
      .map(
        (c) =>
          `<button type="button" class="cat-jump-btn" data-action="jump-category" data-category-id="${c.id}" style="--cat:${c.color}">${icon(c.icon, { weight: 'duotone' })}<span>${escapeHtml(c.name)}</span></button>`
      )
      .join('')}</nav>`;
  }

  let matches = 0;
  for (const cat of cats) {
    let items = foodsByCategory.get(cat.id) || [];
    if (q) items = items.filter((f) => normalizeName(f.name).includes(q));
    if (items.length === 0) continue;
    matches += items.length;
    const collapsed = !q && collapsedCategories.has(cat.id);
    const inList = items.filter((f) => selectedIds.has(f.id)).length;
    html += `
      <section class="picker-group${collapsed ? ' collapsed' : ''}" data-category-id="${cat.id}" style="--cat:${cat.color}">
        <h3 class="picker-heading">
          <button type="button" class="picker-toggle" data-action="toggle-category" data-category-id="${cat.id}" aria-expanded="${!collapsed}">
            <span class="cat-icon">${icon(cat.icon, { weight: 'duotone' })}</span>
            <span class="picker-cat-name">${escapeHtml(cat.name)}</span>
            ${inList ? `<span class="picker-count">${inList}</span>` : ''}
            ${icon('caret-down', { cls: 'picker-caret' })}
          </button>
        </h3>
        <div class="chip-grid">${items.map((f) => foodChip(f, cat, selectedIds.has(f.id), manage)).join('')}</div>
      </section>`;
  }

  if (q && matches === 0 && !html) html += `<p class="picker-empty">Nessun alimento corrisponde alla ricerca.</p>`;
  container.innerHTML = html;
}

function renderDetail({ animate = false } = {}) {
  const list = getSelectedList();
  if (!list) return;

  // posizioni prima del render, per animare gli spostamenti (FLIP)
  const before = new Map();
  if (animate && !reducedMotion.matches) {
    el.detailItems.querySelectorAll('.item[data-food-id]').forEach((n) => before.set(n.dataset.foodId, n.getBoundingClientRect().top));
  }

  if (document.activeElement !== el.detailTitle) el.detailTitle.textContent = list.name;
  const { total, checked, pct } = listProgress(list);
  el.detailMeta.textContent =
    total === 0
      ? 'Nessun alimento'
      : checked === 0
        ? plural(total, 'alimento', 'alimenti')
        : checked === total
          ? `Tutti i ${total} alimenti presi`
          : `${checked} di ${total} presi`;
  el.detailProgress.style.width = `${pct}%`;
  el.doneBanner.classList.toggle('hidden', !(total > 0 && checked === total && !list.archived));
  el.detailEmpty.classList.toggle('hidden', total > 0);
  if (el.closeListBtn) el.closeListBtn.classList.toggle('hidden', total === 0);

  const byStore = list.groupBy === 'store' && list.items.some((i) => i.store);
  const today = todayIso();
  const groups = groupItemsForDetail(list, byStore);

  el.detailItems.innerHTML = groups
    .map((g) => {
      const entries = g.entries;
      entries.sort((a, b) => a.item.checked - b.item.checked || a.food.name.localeCompare(b.food.name, 'it'));
      const done = entries.filter((e) => e.item.checked).length;
      const rows = entries
        .map(({ food, item }) => {
          const qty = formatQty(item.qty);
          const cat = categoryById(food.category);
          const st = item.store;
          const expired = st && st.validTo && st.validTo < today;
          const storeLine = st
            ? `<span class="item-store${expired ? ' is-expired' : ''}">${byStore ? '' : `${escapeHtml(st.chainName)} · `}${formatEuro(st.price)}${st.unitPrice ? ` · ${escapeHtml(st.unitPrice)}` : ''}${expired ? ' · offerta scaduta' : st.validTo ? ` · fino al ${formatShortDate(st.validTo)}` : ''}</span>`
            : '';
          return `
          <li class="item${item.checked ? ' checked' : ''}" data-food-id="${food.id}" style="--cat:${g.isOffers ? g.color : cat.color}">
            <div class="item-swipe-bg" aria-hidden="true">${icon('trash')}<span>Togli</span></div>
            <div class="item-row">
              <button type="button" class="item-check" data-action="toggle-check" data-food-id="${food.id}" role="checkbox" aria-checked="${!!item.checked}" aria-label="${escapeHtml(food.name)}">
                <span class="check-box">${icon('check')}</span>
                <span class="item-icon">${icon(food.icon, { weight: 'duotone' })}</span>
                <span class="item-text">
                  <span class="item-name">${escapeHtml(food.name)}</span>
                  ${item.note ? `<span class="item-note">${escapeHtml(item.note)}</span>` : ''}
                  ${storeLine}
                </span>
              </button>
              <button type="button" class="item-qty${qty ? ' has-qty' : ' is-empty'}" data-action="edit-item" data-food-id="${food.id}" aria-label="${qty ? `Modifica quantità (${escapeHtml(qty)}) per ${escapeHtml(food.name)}` : `Aggiungi quantità o nota per ${escapeHtml(food.name)}`}" title="${qty ? 'Modifica quantità' : 'Aggiungi o modifica quantità'}">
                <span class="qty-pill">
                  ${qty 
                    ? `<span class="qty-val">${escapeHtml(qty)}</span>${icon('pencil-simple', { cls: 'qty-edit-ico' })}` 
                    : `${icon('plus-minus', { cls: 'qty-ico' })}<span class="qty-text">Qtà</span>`
                  }
                </span>
              </button>
            </div>
          </li>`;
        })
        .join('');
      const total = entries.reduce((s, e) => s + (e.item.store && !e.item.checked ? e.item.store.price : 0), 0);
      const count = byStore && g.store && total > 0 ? `≈ ${formatEuro(total)} · ${done}/${entries.length}` : `${done}/${entries.length}`;
      return `
        <section class="detail-group${g.store ? ' is-store' : ''}${g.isOffers ? ' is-offers' : ''}" style="--cat:${g.color}">
          <h2 class="detail-group-title">
            <span class="cat-icon">${icon(g.icon, { weight: 'duotone' })}</span>
            <span>${escapeHtml(g.name)}</span>
            ${g.isOffers ? '<span class="badge-group-offer">Offerta</span>' : ''}
            <span class="detail-group-count">${count}</span>
          </h2>
          <ul class="item-list">${rows}</ul>
        </section>`;
    })
    .join('');

  if (before.size) {
    el.detailItems.querySelectorAll('.item[data-food-id]').forEach((n) => {
      const prev = before.get(n.dataset.foodId);
      if (prev == null) return;
      const dy = prev - n.getBoundingClientRect().top;
      if (Math.abs(dy) < 1) return;
      n.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], {
        duration: 320,
        easing: 'cubic-bezier(.2,.8,.2,1)',
      });
    });
  }
}

// Gruppi del dettaglio: per reparto (default) o per negozio dopo "Dividi la lista per negozio".
function groupItemsForDetail(list, byStore) {
  const entries = list.items.map((item) => ({ item, food: foodsById.get(item.foodId) })).filter((e) => e.food);
  if (!byStore) {
    const offerEntries = entries.filter((e) => e.item.fromOffer || Boolean(e.item.store && e.item.store.offerId));
    const regularEntries = entries.filter((e) => !e.item.fromOffer && !Boolean(e.item.store && e.item.store.offerId));

    const categoryGroups = orderedCategories()
      .map((cat) => ({ name: cat.name, icon: cat.icon, color: cat.color, entries: regularEntries.filter((e) => e.food.category === cat.id) }))
      .filter((g) => g.entries.length);

    if (offerEntries.length > 0) {
      const offerGroup = {
        name: 'Offerte',
        icon: 'seal-percent',
        color: '#d45b34',
        isOffers: true,
        entries: offerEntries,
      };
      return [offerGroup, ...categoryGroups];
    }
    return categoryGroups;
  }
  const groups = new Map();
  for (const e of entries) {
    const key = e.item.store ? e.item.store.chain : '';
    if (!groups.has(key)) {
      groups.set(key, {
        store: !!key,
        name: key ? e.item.store.chainName : 'Senza negozio',
        icon: key ? 'storefront' : 'basket',
        color: key ? chainColor(key) : 'var(--muted)',
        entries: [],
      });
    }
    groups.get(key).entries.push(e);
  }
  // ordine: negozi come scelti nel report, poi gli alimenti senza negozio
  const order = list.storeOrder || [];
  const rank = (k) => (k === '' ? 1e6 : order.includes(k) ? order.indexOf(k) : 1e3);
  return [...groups.entries()].sort(([a], [b]) => rank(a) - rank(b)).map(([, g]) => g);
}

// ---------- SWIPE PER TOGLIERE (delegato sulla lista) ----------

const SWIPE_THRESHOLD = 96;
let swipe = null;
let suppressClickUntil = 0;

el.detailItems.addEventListener('pointerdown', (e) => {
  const li = e.target.closest('.item');
  if (!li || e.button !== 0 || e.target.closest('.item-qty')) return;
  swipe = { li, row: li.querySelector('.item-row'), bg: li.querySelector('.item-swipe-bg'), x: e.clientX, y: e.clientY, id: e.pointerId, horizontal: null };
});

el.detailItems.addEventListener('pointermove', (e) => {
  if (!swipe || e.pointerId !== swipe.id) return;
  const dx = e.clientX - swipe.x;
  const dy = e.clientY - swipe.y;
  if (swipe.horizontal === null) {
    if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
    swipe.horizontal = Math.abs(dx) > Math.abs(dy) * 1.2;
    if (!swipe.horizontal) {
      swipe = null;
      return;
    }
    swipe.li.setPointerCapture(e.pointerId);
    swipe.row.style.transition = 'none';
  }
  const x = Math.min(0, dx);
  swipe.row.style.transform = `translateX(${x}px)`;
  swipe.bg.style.opacity = String(Math.min(1, -x / SWIPE_THRESHOLD));
  swipe.li.classList.toggle('swipe-armed', -x >= SWIPE_THRESHOLD);
});

function endSwipe(e, cancelled) {
  if (!swipe || e.pointerId !== swipe.id) return;
  const s = swipe;
  swipe = null;
  if (!s.horizontal) return;
  suppressClickUntil = Date.now() + 350;
  const dx = e.clientX - s.x;
  s.row.style.transition = '';
  if (!cancelled && dx <= -SWIPE_THRESHOLD) {
    s.row.style.transform = 'translateX(-100%)';
    haptic(12);
    setTimeout(() => removeItemWithUndo(Number(s.li.dataset.foodId)), 160);
  } else {
    s.row.style.transform = '';
    s.bg.style.opacity = '0';
    s.li.classList.remove('swipe-armed');
  }
}

el.detailItems.addEventListener('pointerup', (e) => endSwipe(e, false));
el.detailItems.addEventListener('pointercancel', (e) => endSwipe(e, true));

// ---------- AZIONI SULLE LISTE ----------

async function newList() {
  const list = await createList();
  navigate('detail', { listId: list.id });
  openQuickAdd();
}

function toggleCheck(foodId) {
  const list = getSelectedList();
  const item = list && list.items.find((i) => i.foodId === foodId);
  if (!item) return;
  item.checked = !item.checked;
  persistList(list);
  haptic(item.checked ? 10 : 5);
  renderDetail({ animate: true });
  if (item.checked && list.items.every((i) => i.checked)) haptic([12, 60, 12]);
}

function removeItemWithUndo(foodId) {
  const list = getSelectedList();
  if (!list) return;
  const idx = list.items.findIndex((i) => i.foodId === foodId);
  if (idx < 0) return;
  const [removed] = list.items.splice(idx, 1);
  persistList(list);
  render();
  const food = foodsById.get(foodId);
  showToast(`${food ? food.name : 'Alimento'} tolto dalla lista`, {
    actionLabel: 'Annulla',
    onAction: () => {
      list.items.splice(Math.min(idx, list.items.length), 0, removed);
      persistList(list);
      render();
    },
  });
}

function uncheckAll() {
  const list = getSelectedList();
  if (!list) return;
  const snapshot = list.items.map((i) => i.checked);
  if (!snapshot.some(Boolean)) {
    showToast('Nessun alimento spuntato');
    return;
  }
  list.items.forEach((i) => (i.checked = false));
  persistList(list);
  render();
  showToast('Spunte tolte', {
    actionLabel: 'Annulla',
    onAction: () => {
      list.items.forEach((i, n) => (i.checked = snapshot[n]));
      persistList(list);
      render();
    },
  });
}

function archiveList() {
  const list = getSelectedList();
  if (!list || list.archived) return;
  list.archived = true;
  list.archivedAt = Date.now();
  persistList(list);
  setShoppingMode(false);
  leaveDetail();
  showToast(`“${list.name}” chiusa e salvata nello storico`, {
    actionLabel: 'Annulla',
    onAction: () => {
      list.archived = false;
      delete list.archivedAt;
      persistList(list);
      render();
    },
  });
}

function deleteSelectedList() {
  const list = getSelectedList();
  if (!list) return;
  confirmAction(`Eliminare “${list.name}”? Non potrai recuperarla.`, async () => {
    await deleteList(list.id);
    lists = lists.filter((l) => l.id !== list.id);
    selectedListId = null;
    leaveDetail();
    showToast('Lista eliminata');
  });
}

function deleteArchived(id) {
  const list = getList(id);
  if (!list) return;
  confirmAction(`Eliminare “${list.name}” dallo storico?`, async () => {
    await deleteList(id);
    lists = lists.filter((l) => l.id !== id);
    render();
  });
}

async function restoreArchivedList(id) {
  const source = getList(id);
  if (!source) return;
  const baseName = source.name.replace(/\s*\(copia\d*\)$/i, '').replace(/\s*\((reintegrata|ripetuta)\)$/i, '');
  const existingNames = new Set(activeLists().map((l) => l.name));
  let newName = baseName;
  let counter = 1;
  while (existingNames.has(newName)) {
    counter++;
    newName = `${baseName} (copia ${counter})`;
  }
  const copy = await createList({
    name: newName,
    items: source.items.map(({ foodId, qty, note, store, fromOffer }) => ({
      foodId,
      checked: false,
      ...(qty ? { qty } : {}),
      ...(note ? { note } : {}),
      ...(store ? { store } : {}),
      ...(fromOffer ? { fromOffer } : {}),
    })),
  });
  navigate('detail', { listId: copy.id });
  showToast(`“${copy.name}” creata! Pronta per la spesa.`, {
    actionLabel: 'Le mie liste',
    onAction: () => navigate('lists'),
  });
}

async function copyListToNew(id) {
  const source = getList(id);
  if (!source) return;
  const name = source.archived ? source.name : `${source.name} (copia)`;
  const copy = await createList({
    name: activeLists().some((l) => l.name === name) ? `${name} (copia)` : name,
    items: source.items.map(({ foodId, qty, note, store, fromOffer }) => ({ foodId, checked: false, ...(qty ? { qty } : {}), ...(note ? { note } : {}), ...(store ? { store } : {}), ...(fromOffer ? { fromOffer } : {}) })),
  });
  navigate('detail', { listId: copy.id, replace: route.view === 'detail' });
  showToast(source.archived ? 'Lista riaperta con tutti gli alimenti da prendere' : 'Lista duplicata');
}

function renameSelectedList(name) {
  const list = getSelectedList();
  const clean = name.replace(/\s+/g, ' ').trim();
  if (!list) return;
  if (!clean) {
    el.detailTitle.textContent = list.name;
    return;
  }
  if (clean !== list.name) {
    list.name = clean;
    persistList(list);
  }
  el.detailTitle.textContent = clean;
}

function focusTitleEnd() {
  el.detailTitle.focus();
  const range = document.createRange();
  range.selectNodeContents(el.detailTitle);
  range.collapse(false);
  const sel = window.getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
}

// ---------- MODALITÀ SPESA ----------

let wakeLock = null;

async function requestWakeLock() {
  if (!('wakeLock' in navigator) || document.visibilityState !== 'visible') return;
  try {
    wakeLock = await navigator.wakeLock.request('screen');
    wakeLock.addEventListener('release', () => (wakeLock = null));
  } catch {
    wakeLock = null;
  }
}

function setShoppingMode(on) {
  if (shoppingMode === on) return;
  shoppingMode = on;
  if (on) requestWakeLock();
  else if (wakeLock) wakeLock.release().catch(() => {});
  if (route.view === 'detail') renderDetail();
}

document.addEventListener('visibilitychange', () => {
  if (shoppingMode && document.visibilityState === 'visible' && !wakeLock) requestWakeLock();
});

// ---------- AGGIUNTA RAPIDA ----------

function openQuickAdd() {
  if (!getSelectedList()) return;
  quickAddQuery = '';
  el.quickAddSearch.value = '';
  renderQuickAdd();
  el.quickAddPicker.scrollTop = 0;
  openSheet('quickAdd', { onClose: () => render() });
}

function quickAddCountText(list) {
  return list.items.length === 0 ? 'Tocca un alimento per aggiungerlo' : `${plural(list.items.length, 'alimento', 'alimenti')} in lista`;
}

async function toggleFoodFromPicker(foodId, picker) {
  const list = picker === 'catalog' ? await ensureTargetList() : getSelectedList();
  if (!list) return;
  const added = toggleFoodInList(list, foodId);
  haptic(added ? 10 : 5);
  // aggiornamento locale dei chip, senza ricostruire il catalogo (lo scroll resta fermo)
  const container = picker === 'catalog' ? el.catalogPicker : el.quickAddPicker;
  container.querySelectorAll(`.chip-main[data-food-id="${foodId}"]`).forEach((btn) => {
    btn.closest('.chip').classList.toggle('selected', added);
    btn.setAttribute('aria-pressed', String(added));
  });
  const food = foodsById.get(foodId);
  const group = container.querySelector(`.picker-group[data-category-id="${food.category}"]`);
  if (group) {
    const n = group.querySelectorAll('.chip.selected').length;
    let badge = group.querySelector('.picker-count');
    if (n && !badge) {
      badge = document.createElement('span');
      badge.className = 'picker-count';
      group.querySelector('.picker-cat-name').after(badge);
    }
    if (badge && n) badge.textContent = n;
    else if (badge) badge.remove();
  }
  if (picker === 'catalog') {
    renderChrome();
    renderTargetSelect();
  } else {
    el.quickAddCount.textContent = quickAddCountText(list);
  }
}

async function createFromSearch(picker) {
  const input = picker === 'catalog' ? el.catalogSearch : el.quickAddSearch;
  const raw = input.value.replace(/\s+/g, ' ').trim();
  if (!raw) return;
  const name = capitalize(raw);
  const { category, icon: iconName } = guessCategoryAndIcon(name);
  const saved = await addFood({ name, category, icon: iconName, custom: true });
  foods.push(saved);
  rebuildFoodIndexes();
  const list = picker === 'catalog' ? await ensureTargetList() : getSelectedList();
  if (list) toggleFoodInList(list, saved.id);
  input.value = '';
  if (picker === 'catalog') catalogQuery = '';
  else quickAddQuery = '';
  render();
  haptic(10);
  showToast(`${name} aggiunto in ${categoryById(category).name}`, {
    actionLabel: 'Modifica',
    onAction: () => openFoodSheet(saved.id),
  });
}

function jumpToCategory(container, catId) {
  collapsedCategories.delete(catId);
  const group = container.querySelector(`.picker-group[data-category-id="${catId}"]`);
  if (!group) return;
  group.classList.remove('collapsed');
  group.scrollIntoView({ behavior: reducedMotion.matches ? 'auto' : 'smooth', block: 'start' });
}

// ---------- QUANTITÀ E NOTA ----------

function openItemEdit(foodId) {
  const list = getSelectedList();
  const item = list && list.items.find((i) => i.foodId === foodId);
  const food = foodsById.get(foodId);
  if (!item || !food) return;
  editingFoodId = foodId;
  const cat = categoryById(food.category);
  el.itemEditIcon.style.setProperty('--cat', cat.color);
  el.itemEditIcon.innerHTML = icon(food.icon, { weight: 'duotone' });
  el.itemEditName.textContent = food.name;
  el.itemEditCategory.textContent = cat.name;
  el.qtyInput.value = item.qty || '';
  el.noteInput.value = item.note || '';
  const st = item.store;
  $('itemStoreRow').classList.toggle('hidden', !st);
  if (st) {
    $('itemStoreName').textContent = st.chainName;
    $('itemStoreInfo').textContent = [st.product, formatEuro(st.price), st.validTo ? 'fino al ' + formatShortDate(st.validTo) : ''].filter(Boolean).join(' · ');
  }
  openSheet('itemEdit', { onClose: saveItemEdit });
}

function saveItemEdit() {
  const list = getSelectedList();
  const item = list && list.items.find((i) => i.foodId === editingFoodId);
  editingFoodId = null;
  if (!item) return;
  const qty = el.qtyInput.value.replace(/\s+/g, ' ').trim();
  const note = el.noteInput.value.replace(/\s+/g, ' ').trim();
  if (qty && qty !== '1') item.qty = qty;
  else delete item.qty;
  if (note) item.note = note;
  else delete item.note;
  persistList(list);
  render();
}

// Stepper: numeri semplici ±1, grammi a passi di 100/250, kg e litri a mezzi.
function stepQty(dir) {
  const v = el.qtyInput.value.trim();
  const m = v.match(/^(\d+(?:[.,]\d+)?)\s*(.*)$/);
  if (v && !m) return;
  const num = m ? parseFloat(m[1].replace(',', '.')) : 1;
  const unit = m ? m[2] : '';
  let step = 1;
  if (/^(g|gr|ml)$/i.test(unit)) step = num >= 500 ? 250 : 100;
  else if (/^(kg|l)$/i.test(unit)) step = 0.5;
  const next = Math.max(step, Math.round((num + dir * step) * 100) / 100);
  el.qtyInput.value = `${String(next).replace('.', ',')}${unit ? ' ' + unit : ''}`;
}

function removeEditingItem() {
  const foodId = editingFoodId;
  editingFoodId = null; // evita il salvataggio in chiusura
  closeAllSheets(() => removeItemWithUndo(foodId));
}

// ---------- NUOVO / MODIFICA ALIMENTO ----------

function openFoodSheet(foodId = null, presetName = '') {
  const food = foodId ? foodsById.get(foodId) : null;
  foodSheetEditId = food ? food.id : null;
  el.foodSheetTitle.textContent = food ? 'Modifica alimento' : 'Nuovo alimento';
  el.foodSaveBtn.textContent = food ? 'Salva modifiche' : 'Salva alimento';
  el.foodName.value = food ? food.name : presetName;
  el.foodCategory.innerHTML = orderedCategories()
    .map((c) => `<option value="${c.id}">${escapeHtml(c.name)}</option>`)
    .join('');
  const guess = !food && presetName ? guessCategoryAndIcon(presetName) : null;
  el.foodCategory.value = food ? food.category : guess ? guess.category : orderedCategories()[0].id;
  foodSheetIcon = food ? food.icon : guess ? guess.icon : null;
  renderIconPicker();
  el.foodDeleteBtn.classList.toggle('hidden', !food);
  closeAllSheets(() => openSheet('food'));
}

function renderIconPicker() {
  const catId = el.foodCategory.value;
  const cat = categoryById(catId);
  const base = ICONS_BY_CATEGORY[catId] || [];
  const all = foodSheetIcon && !base.includes(foodSheetIcon) ? [foodSheetIcon, ...base] : base;
  if (!foodSheetIcon || !all.includes(foodSheetIcon)) foodSheetIcon = all[0];
  el.iconPicker.style.setProperty('--cat', cat.color);
  el.iconPicker.innerHTML = all
    .map(
      (name) =>
        `<button type="button" class="icon-choice${name === foodSheetIcon ? ' selected' : ''}" data-action="pick-icon" data-icon-name="${name}" role="radio" aria-checked="${name === foodSheetIcon}" aria-label="${name}">${icon(name, { weight: 'duotone' })}</button>`
    )
    .join('');
}

async function saveFoodSheet() {
  const name = el.foodName.value.replace(/\s+/g, ' ').trim();
  const category = el.foodCategory.value;
  if (!name) {
    showToast('Scrivi il nome dell’alimento');
    el.foodName.focus();
    return;
  }
  const duplicate = foods.find((f) => normalizeName(f.name) === normalizeName(name) && f.id !== foodSheetEditId);
  if (duplicate) {
    showToast(`${duplicate.name} è già nel catalogo`);
    el.foodName.focus();
    return;
  }
  if (foodSheetEditId) {
    const food = foodsById.get(foodSheetEditId);
    Object.assign(food, { name, category, icon: foodSheetIcon });
    await putFood(food);
    showToast('Alimento aggiornato');
  } else {
    const saved = await addFood({ name, category, icon: foodSheetIcon, custom: true });
    foods.push(saved);
    showToast(`${name} aggiunto al catalogo`);
  }
  rebuildFoodIndexes();
  catalogQuery = '';
  el.catalogSearch.value = '';
  closeAllSheets(() => render());
}

function deleteFoodFromSheet() {
  const food = foodsById.get(foodSheetEditId);
  if (!food) return;
  const usedIn = lists.filter((l) => l.items.some((i) => i.foodId === food.id)).length;
  const extra = usedIn ? ` Verrà tolto anche da ${plural(usedIn, 'lista', 'liste')}.` : '';
  confirmAction(`Eliminare “${food.name}” dal catalogo?${extra}`, async () => {
    await deleteFood(food.id);
    foods = foods.filter((f) => f.id !== food.id);
    rebuildFoodIndexes();
    lists.forEach((l) => {
      const before = l.items.length;
      l.items = l.items.filter((i) => i.foodId !== food.id);
      if (l.items.length !== before) persistList(l);
    });
    render();
    showToast('Alimento eliminato');
  });
}

// ---------- FOTO DELLA LISTA ----------

async function openPhoto() {
  const list = getSelectedList();
  if (!list) return;
  if (list.items.length === 0) {
    closeAllSheets(() => showToast('Aggiungi qualche alimento prima di creare la foto'));
    return;
  }
  const token = ++photoToken;
  clearPhoto();
  closeAllSheets(async () => {
    el.photoPreview.removeAttribute('src');
    el.photoInfo.textContent = 'Preparo l’immagine…';
    el.photoShareBtn.disabled = true;
    openSheet('photo', {
      onClose: () => {
        photoToken++; // un render ancora in corso verrà scartato
        clearPhoto();
      },
    });
    try {
      const res = await renderListImage(list, foodsById, orderedCategories());
      if (token !== photoToken) return;
      el.photoShareBtn.disabled = false;
      const file = new File([res.blob], imageFileName(list.name), { type: 'image/png' });
      photoResult = { ...res, url: URL.createObjectURL(res.blob), file };
      el.photoPreview.src = photoResult.url;
      const fmt = res.format === 'lunga' ? 'formato lungo' : `formato ${res.format}`;
      el.photoInfo.textContent = `${res.width}×${res.height}, ${fmt}, ${plural(res.cols, 'colonna', 'colonne')}`;
      const canShareFile = navigator.canShare && navigator.canShare({ files: [file] });
      el.photoShareBtn.classList.toggle('hidden', !canShareFile);
    } catch (err) {
      if (token === photoToken) el.photoInfo.textContent = `Non è stato possibile creare l’immagine: ${err.message}`;
    }
  });
}

let photoToken = 0;

function clearPhoto() {
  if (photoResult) URL.revokeObjectURL(photoResult.url);
  photoResult = null;
}

function downloadPhoto() {
  if (!photoResult) return;
  const a = document.createElement('a');
  a.href = photoResult.url;
  a.download = photoResult.file.name;
  a.click();
  showToast('Immagine salvata');
}

async function sharePhoto() {
  if (!photoResult) return;
  try {
    await navigator.share({ files: [photoResult.file], title: getSelectedList()?.name || 'Lista della spesa' });
  } catch (err) {
    if (err.name !== 'AbortError') showToast('Condivisione non riuscita');
  }
}

// Condivisione e appunti partono subito, dentro il gesto dell'utente (Safari lo richiede);
// il menu si chiude in parallelo.
async function shareListText(mode) {
  const list = getSelectedList();
  if (!list) return;
  const text = buildListText(list, foodsById, orderedCategories());
  const job = mode === 'share' ? shareText(list.name, text) : copyText(text).then(() => 'copied');
  closeAllSheets();
  try {
    if ((await job) === 'copied') showToast('Testo copiato negli appunti');
  } catch (err) {
    if (err.name !== 'AbortError') showToast('Non è stato possibile copiare il testo');
  }
}

// ---------- ORDINE DEI REPARTI ----------

function renderCategoryOrder() {
  const cats = orderedCategories();
  el.categoryOrderList.innerHTML = cats
    .map(
      (c, i) => `
      <li class="order-item" data-category-id="${c.id}" style="--cat:${c.color}">
        <span class="order-handle" aria-hidden="true">${icon('dots-six-vertical')}</span>
        <span class="cat-icon">${icon(c.icon, { weight: 'duotone' })}</span>
        <span class="order-name">${escapeHtml(c.name)}</span>
        <button type="button" class="icon-btn icon-btn-sm" data-action="move-category" data-dir="-1" data-category-id="${c.id}" aria-label="Sposta su ${escapeHtml(c.name)}" ${i === 0 ? 'disabled' : ''}>${icon('arrow-up')}</button>
        <button type="button" class="icon-btn icon-btn-sm" data-action="move-category" data-dir="1" data-category-id="${c.id}" aria-label="Sposta giù ${escapeHtml(c.name)}" ${i === cats.length - 1 ? 'disabled' : ''}>${icon('arrow-down')}</button>
      </li>`
    )
    .join('');
}

function saveCategoryOrder(ids) {
  categoryOrder = ids;
  setSetting('categoryOrder', ids);
  renderCategoryOrder();
  render();
}

function moveCategory(id, dir) {
  const ids = orderedCategories().map((c) => c.id);
  const i = ids.indexOf(id);
  const j = i + dir;
  if (j < 0 || j >= ids.length) return;
  [ids[i], ids[j]] = [ids[j], ids[i]];
  saveCategoryOrder(ids);
  const btn = el.categoryOrderList.querySelector(`[data-category-id="${id}"] [data-dir="${dir}"]`);
  (btn && !btn.disabled ? btn : el.categoryOrderList.querySelector(`[data-category-id="${id}"] button:not([disabled])`))?.focus();
}

// Trascinamento dalla maniglia (pointer events: funziona con mouse e touch).
let drag = null;

el.categoryOrderList.addEventListener('pointerdown', (e) => {
  const handle = e.target.closest('.order-handle');
  if (!handle) return;
  e.preventDefault();
  const li = handle.closest('.order-item');
  const rect = li.getBoundingClientRect();
  drag = { li, startY: e.clientY, offset: 0, height: rect.height + 6, pointerId: e.pointerId };
  li.classList.add('dragging');
  el.categoryOrderList.setPointerCapture(e.pointerId);
});

el.categoryOrderList.addEventListener('pointermove', (e) => {
  if (!drag) return;
  const dy = e.clientY - drag.startY - drag.offset;
  drag.li.style.transform = `translateY(${dy}px)`;
  const sibling = dy > drag.height / 2 ? drag.li.nextElementSibling : dy < -drag.height / 2 ? drag.li.previousElementSibling : null;
  if (sibling) {
    if (dy > 0) sibling.after(drag.li);
    else sibling.before(drag.li);
    drag.offset += dy > 0 ? drag.height : -drag.height;
    drag.li.style.transform = `translateY(${e.clientY - drag.startY - drag.offset}px)`;
    haptic(5);
  }
});

function endDrag() {
  if (!drag) return;
  drag.li.classList.remove('dragging');
  drag.li.style.transform = '';
  drag = null;
  saveCategoryOrder([...el.categoryOrderList.children].map((li) => li.dataset.categoryId));
}

el.categoryOrderList.addEventListener('pointerup', endDrag);
el.categoryOrderList.addEventListener('pointercancel', endDrag);

function openCategoryOrder() {
  renderCategoryOrder();
  closeAllSheets(() => openSheet('categoryOrder'));
}

// ---------- BACKUP ----------

// Il file di backup si prepara all'apertura del menu: così la condivisione può partire
// direttamente dal tocco su "Salva backup" (Safari non la consente dopo un'attesa).
let preparedBackup = null;

async function prepareBackup() {
  const data = await exportAllData();
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const name = `spesa-backup-${new Date().toISOString().slice(0, 10)}.json`;
  preparedBackup = { data, blob, name, file: new File([blob], name, { type: 'application/json' }) };
  return preparedBackup;
}

async function exportBackup() {
  const backup = preparedBackup || (await prepareBackup());
  preparedBackup = null;
  const { data, blob, name, file } = backup;
  const summary = `${plural(data.lists.length, 'lista', 'liste')}, ${plural(data.foods.length, 'alimento', 'alimenti')}`;
  if (navigator.canShare && navigator.canShare({ files: [file] }) && matchMedia('(pointer: coarse)').matches) {
    const job = navigator.share({ files: [file], title: 'Backup Spesa' });
    closeAllSheets();
    try {
      await job;
      return;
    } catch (err) {
      if (err.name === 'AbortError') return;
    }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  closeAllSheets(() => showToast(`Backup salvato: ${summary}`));
}

function validateBackup(data) {
  if (!data || typeof data !== 'object' || !Array.isArray(data.foods) || !Array.isArray(data.lists)) {
    throw new Error('il file non è un backup di Spesa');
  }
  const foodIds = new Set();
  for (const f of data.foods) {
    if (typeof f.id !== 'number' || typeof f.name !== 'string' || typeof f.category !== 'string') throw new Error('alimenti non validi');
    foodIds.add(f.id);
  }
  for (const l of data.lists) {
    if (typeof l.id !== 'number' || typeof l.name !== 'string' || !Array.isArray(l.items)) throw new Error('liste non valide');
    l.items = l.items.filter((i) => foodIds.has(i.foodId));
  }
  return data;
}

async function importBackup(file) {
  let data;
  try {
    data = validateBackup(JSON.parse(await file.text()));
  } catch (err) {
    showToast(`Ripristino non riuscito: ${err.message}`);
    return;
  }
  confirmAction(
    `Ripristinare ${plural(data.lists.length, 'lista', 'liste')} e ${plural(data.foods.length, 'alimento', 'alimenti')}? I dati attuali verranno sostituiti.`,
    async () => {
      try {
        await replaceAllData(data);
        await loadData();
      } catch (err) {
        showToast(`Ripristino non riuscito: ${err.message || 'errore del database'}`);
        return;
      }
      navigate('lists', { replace: true });
      render();
      showToast('Backup ripristinato');
    },
    { confirmLabel: 'Ripristina' }
  );
}

el.importFile.addEventListener('change', () => {
  const file = el.importFile.files[0];
  el.importFile.value = '';
  if (file) importBackup(file);
});

// ---------- OFFERTE ----------

const offersState = {
  place: null, // { label, lat, lon, radiusKm }
  draftRadius: 1,
  config: null, // { chains, cities }
  stores: null,
  storesError: null,
  loadingStores: false,
  city: null,
  data: null,
  dataError: null,
  loadingData: false,
  expandedStores: new Set(),
  expandedAllStores: new Set(),
  offersFilter: '',
  selectedCategory: null,
  hasUserToggled: false,
};

function chainColor(slug) {
  const c = offersState.config && offersState.config.chains.find((x) => x.slug === slug);
  return c ? c.color : 'var(--basil)';
}

async function ensureOffersConfig() {
  if (!offersState.config) offersState.config = await loadOffersConfig();
  return offersState.config;
}

// Trova e ordina per prezzo crescente tutte le offerte per un determinato supermercato
function getOffersForStore(store) {
  if (!offersState.data || !offersState.config) return [];
  const chain = normalizeChain(store, offersState.config.chains);
  const all = activeOffers(offersState.data.offers);
  if (chain) {
    let list = all.filter((o) => o.chain === chain.slug);
    if (!list.length) {
      const family = chain.slug.split('-')[0];
      list = all.filter((o) => o.chain.startsWith(family));
    }
    if (list.length) {
      return list.slice().sort((a, b) => a.price - b.price);
    }
  }
  // Se supermercato indipendente o senza volantino specifico: migliori alimenti di base sotto 2.50 €
  const staples = all.filter((o) => o.price <= 2.5).slice(0, 30);
  return staples.sort((a, b) => a.price - b.price);
}

let pendingOfferToAdd = null;

function openTargetListModal(offer, storeName) {
  pendingOfferToAdd = { offer, storeName };
  const al = activeLists();
  const badge = $('targetListProductBadge');
  if (badge) {
    badge.innerHTML = `
      <span class="badge-icon">${icon('seal-percent', { weight: 'duotone' })}</span>
      <span class="badge-text"><strong>${escapeHtml(offer.name)}</strong> · ${formatEuro(offer.price)}${storeName ? ` (${escapeHtml(storeName)})` : ''}</span>
    `;
  }
  const container = $('targetListOptions');
  if (container) {
    container.innerHTML =
      al
        .map(
          (l) => `
        <button type="button" class="target-list-choice" data-action="choose-target-list" data-list-id="${l.id}">
          <div class="choice-icon">${icon('list-checks', { weight: 'duotone' })}</div>
          <div class="choice-info">
            <span class="choice-name">${escapeHtml(l.name)}</span>
            <span class="choice-meta">${plural(l.items.length, 'alimento', 'alimenti')}${l.items.length > 0 ? ` · ${l.items.filter((i) => i.checked).length} presi` : ''}</span>
          </div>
          <span class="choice-arrow">${icon('caret-right')}</span>
        </button>`
        )
        .join('') +
      `
      <button type="button" class="target-list-choice is-new" data-action="choose-target-list" data-list-id="new">
        <div class="choice-icon">${icon('plus')}</div>
        <div class="choice-info">
          <span class="choice-name">Crea nuova lista</span>
          <span class="choice-meta">Aggiungi questa offerta in una nuova lista</span>
        </div>
        <span class="choice-arrow">${icon('caret-right')}</span>
      </button>`;
  }
  openSheet('targetList');
}

// Aggiunge un alimento in offerta a una lista specifica (nella sezione Offerte)
async function addOfferToSpecificList(offer, storeName, list) {
  if (!list) return;
  const searchName = offer.foodName || offer.name;
  let food = foods.find((f) => normalizeName(f.name) === normalizeName(searchName));
  if (!food) {
    const { category, icon: iconName } = guessCategoryAndIcon(offer.name);
    food = await addFood({ name: capitalize(offer.name), category, icon: iconName, custom: true });
    foods.push(food);
    foodsById.set(food.id, food);
  }
  let item = list.items.find((i) => i.foodId === food.id);
  const noteText = `${offer.brand ? offer.brand + ' · ' : ''}${formatEuro(offer.price)}${storeName ? ` (${storeName})` : ''}`;
  const storeData = {
    chain: offer.chain,
    chainName: storeName || offer.chainName,
    offerId: offer.id,
    product: [offer.brand, offer.name].filter(Boolean).join(' '),
    price: offer.price,
    unitPrice: offer.unitPrice ? formatUnitPrice(offer.unitPrice) : '',
    validTo: offer.validTo,
  };
  if (!item) {
    item = {
      foodId: food.id,
      checked: false,
      note: noteText,
      store: storeData,
      fromOffer: true,
    };
    list.items.push(item);
  } else {
    item.note = noteText;
    item.store = storeData;
    item.fromOffer = true;
  }
  await persistList(list);
  haptic(10);
  showToast(`Aggiunto a “${list.name}”: ${offer.name} (${formatEuro(offer.price)})`, {
    actionLabel: 'Apri lista',
    onAction: () => navigate('detail', { listId: list.id }),
  });
}

// Aggiunge un alimento in offerta: se ci sono più liste attive apre la modale di selezione
async function addOfferToList(offer, storeName) {
  const al = activeLists();
  if (al.length > 1) {
    openTargetListModal(offer, storeName);
  } else if (al.length === 1) {
    await addOfferToSpecificList(offer, storeName, al[0]);
  } else {
    const newList = await createList();
    await addOfferToSpecificList(offer, storeName, newList);
  }
}

let offersRequest = 0;

async function refreshOffers() {
  offersLoaded = true;
  const req = ++offersRequest;
  const current = () => req === offersRequest;
  const { place } = offersState;
  if (!place) {
    render();
    return;
  }
  const config = await ensureOffersConfig().catch(() => null);
  if (!current()) return;
  if (!config) {
    offersState.storesError = 'Configurazione non disponibile';
    render();
    return;
  }
  offersState.city = coveredCity(place.lat, place.lon, config.cities) || { id: 'roma', name: place.label || 'Tutta Italia' };
  offersState.stores = null;
  offersState.loadingStores = true;
  offersState.storesError = null;
  offersState.dataError = null;
  offersState.loadingData = !offersState.data;
  render();

  const storesJob = findStores(place.lat, place.lon, place.radiusKm).then(
    (s) => current() && (offersState.stores = s),
    (err) => current() && (offersState.storesError = err.message)
  );
  const dataJob = offersState.loadingData
    ? loadCityOffers(offersState.city.id).then(
        (d) => {
          if (!current()) return;
          offersState.data = d;
          offersState.dataError = d ? null : 'Offerte non ancora disponibili';
        },
        () => {
          if (!current()) return;
          offersState.data = null;
          offersState.dataError = 'Offerte non raggiungibili. Controlla la connessione.';
        }
      )
    : Promise.resolve();
  await Promise.all([storesJob, dataJob]);
  if (!current()) return;
  offersState.loadingStores = false;
  offersState.loadingData = false;
  if (route.view === 'offers') render();
}

let offersLoaded = false;

function renderOffers() {
  if (!offersLoaded && offersState.place) {
    offersLoaded = true;
    refreshOffers();
    return;
  }
  const { place } = offersState;
  $('placeLabel').textContent = place ? place.label : 'Scegli una posizione';
  $('placeMeta').textContent = place ? `Entro ${formatKm(place.radiusKm)}` : 'Cerca i supermercati intorno a te';
  renderRadiusPicker();

  const status = $('offersStatus');
  const data = offersState.data;
  let statusHtml = '';
  if (offersState.dataError) {
    statusHtml = `${icon('cloud-slash')}<span>${escapeHtml(offersState.dataError)}</span>`;
  }
  status.innerHTML = statusHtml;
  status.classList.toggle('hidden', !statusHtml);
  $('offersSource').innerHTML = data
    ? `Offerte dei volantini aggiornate · Fonte: ${escapeHtml(data.source?.name || 'Volantini')}.`
    : '';

  const body = $('offersBody');
  if (!place) {
    body.innerHTML = `
      <div class="empty-state">
        <p class="empty-title">Dove fai la spesa?</p>
        <p class="empty-text">Scegli la tua posizione e una distanza (500 m, 1 km o più): trovo tutti i supermercati vicini e confronto le offerte più economiche per ciascuno.</p>
        <button class="btn btn-primary" data-action="open-place">${icon('map-pin')}Scegli la posizione</button>
      </div>`;
    return;
  }
  if (offersState.loadingStores || offersState.loadingData) {
    body.innerHTML = `<div class="offers-loading"><span class="spinner" aria-hidden="true"></span>Cerco i supermercati e confronto le offerte più convenienti…</div>`;
    return;
  }
  if (offersState.storesError) {
    body.innerHTML = `<div class="empty-state"><p class="empty-title">Qualcosa non ha funzionato</p><p class="empty-text">${escapeHtml(offersState.storesError)}</p><button class="btn btn-primary" data-action="offers-retry">${icon('arrows-clockwise')}Riprova</button></div>`;
    return;
  }

  body.innerHTML = renderStoresList();
}

function buildStoreCardsHtml() {
  const { stores, config } = offersState;
  if (!stores || !stores.length) return '';
  const filterQuery = (offersState.offersFilter || '').toLowerCase().trim();

  return stores.map((store) => {
    const chain = config ? normalizeChain(store, config.chains) : null;
    const allStoreOffers = getOffersForStore(store);

    let displayedOffers = allStoreOffers;
    if (offersState.selectedCategory) {
      displayedOffers = displayedOffers.filter((o) => o.category === offersState.selectedCategory);
    }
    if (filterQuery) {
      displayedOffers = displayedOffers.filter((o) =>
        (o.name && o.name.toLowerCase().includes(filterQuery)) ||
        (o.brand && o.brand.toLowerCase().includes(filterQuery)) ||
        (o.foodName && o.foodName.toLowerCase().includes(filterQuery))
      );
    }

    if ((filterQuery || offersState.selectedCategory) && displayedOffers.length === 0) {
      return '';
    }

    const isExpanded = offersState.expandedStores.has(store.id) || !!filterQuery || !!offersState.selectedCategory;
    const showAll = offersState.expandedAllStores.has(store.id);
    const limit = showAll ? displayedOffers.length : 8;
    const slice = displayedOffers.slice(0, limit);
    const remaining = displayedOffers.length - limit;

    const minPrice = displayedOffers.length > 0 ? displayedOffers[0].price : null;
    const priceBadge = minPrice != null
      ? `<span class="badge-offers-count">${displayedOffers.length} ${displayedOffers.length === 1 ? 'offerta' : 'offerte'} · da ${formatEuro(minPrice)}</span>`
      : `<span class="badge-offers-count is-none">Nessun volantino</span>`;

    const offersRows = slice.map((o) => offerRow(o, { storeName: store.name || store.brand })).join('');

    const moreBtn = remaining > 0
      ? `<button type="button" class="store-more-btn" data-action="expand-store-all" data-store-id="${store.id}">+ Mostra tutte le ${displayedOffers.length} offerte</button>`
      : '';

    const emptyOffersMsg = displayedOffers.length === 0
      ? `<p class="picker-empty" style="padding:12px 0; color:var(--muted); font-size:var(--fs-sm);">Nessuna offerta attiva per questo negozio al momento.</p>`
      : '';

    return `
      <article class="store-card${isExpanded ? ' is-expanded' : ''}" style="--chain:${chain ? chain.color : 'var(--basil)'}">
        <div class="store-card-header" data-action="toggle-store" data-store-id="${store.id}">
          <div class="store-card-main">
            <span class="store-card-dot" aria-hidden="true"></span>
            <div class="store-card-info">
              <div class="store-card-title-row">
                <span class="store-card-name">${escapeHtml(store.name || store.brand)}</span>
                <span class="badge-km">${formatKm(store.km)}</span>
              </div>
              ${store.address ? `<span class="store-card-sub">${escapeHtml(store.address)}</span>` : ''}
            </div>
          </div>
          <div class="store-card-meta">
            ${priceBadge}
            <a class="icon-btn icon-btn-sm" href="${osmLink(store)}" target="_blank" rel="noopener" aria-label="Apri su mappa" title="Vedi su OpenStreetMap" onclick="event.stopPropagation()">${icon('arrow-square-out')}</a>
            <span class="store-chevron">${icon('caret-down')}</span>
          </div>
        </div>
        <div class="store-card-body${isExpanded ? '' : ' hidden'}">
          ${displayedOffers.length > 0 ? `<ul class="offer-list">${offersRows}</ul>${moreBtn}` : emptyOffersMsg}
        </div>
      </article>`;
  }).filter(Boolean).join('');
}

function updateStoreCardsOnly() {
  const container = document.querySelector('.store-cards-list');
  if (!container) return;
  const cardsHtml = buildStoreCardsHtml();
  container.innerHTML = cardsHtml || '<div class="empty-state"><p class="empty-text">Nessuna offerta trovata per questo filtro di ricerca.</p></div>';
}

function renderStoresList() {
  const { stores } = offersState;
  if (!stores || !stores.length) {
    return `<div class="empty-state"><p class="empty-title">Nessun supermercato</p><p class="empty-text">Non ho trovato supermercati entro ${formatKm(offersState.place.radiusKm)}. Prova ad allargare la distanza a 1 km, 2 km o 3 km.</p></div>`;
  }

  if (offersState.expandedStores.size === 0 && !offersState.hasUserToggled) {
    stores.slice(0, 2).forEach((s) => offersState.expandedStores.add(s.id));
  }

  const catChips = [
    { id: null, name: 'Tutto' },
    ...CATEGORIES.filter((c) => ['ortofrutta', 'latticini', 'carne', 'dispensa', 'bevande', 'surgelati'].includes(c.id))
  ].map((c) => {
    const active = offersState.selectedCategory === c.id;
    return `<button type="button" class="preset-pill${active ? ' active' : ''}" data-action="offers-filter-cat" data-category-id="${c.id || ''}">${escapeHtml(c.name)}</button>`;
  }).join('');

  const storeCardsHtml = buildStoreCardsHtml();

  return `
    <div class="offers-summary-bar">
      <span><strong>${stores.length} supermercati</strong> entro ${formatKm(offersState.place.radiusKm)} · Ordinati per vicinanza e prezzo</span>
    </div>
    <div class="offers-search-bar">
      ${icon('magnifying-glass')}
      <input id="offersSearchInput" type="search" placeholder="Cerca tra le offerte (pasta, latte, caffè, birra…)" value="${escapeHtml(offersState.offersFilter || '')}" enterkeyhint="search" />
      ${offersState.offersFilter ? `<button class="icon-btn icon-btn-sm" type="button" data-action="clear-offers-search" aria-label="Cancella ricerca">${icon('x')}</button>` : ''}
    </div>
    <div class="quick-radius-bar" role="toolbar" aria-label="Filtra per reparto">
      ${catChips}
    </div>
    <div class="store-cards-list" style="display:flex; flex-direction:column; gap:12px;">
      ${storeCardsHtml || '<div class="empty-state"><p class="empty-text">Nessuna offerta trovata per questo filtro di ricerca.</p></div>'}
    </div>`;
}

function offerRow(o, { storeName = '', showChain = false, extra = '', badge = null } = {}) {
  const qty = o.qty && o.qty.value ? `${o.qty.count > 1 ? `${o.qty.count}×` : ''}${String(o.qty.value).replace('.', ',')} ${o.qty.unit}` : '';
  const cat = categoryById(o.category);
  const food = o.foodName ? FOODS.find((f) => f.name === o.foodName) : null;
  return `
    <li class="offer-row" style="--cat:${cat.color}">
      <span class="item-icon">${icon(food ? food.icon : cat.icon, { weight: 'duotone' })}</span>
      <div class="offer-text">
        <span class="offer-name">${escapeHtml(o.name)}</span>
        <span class="offer-meta">${[o.brand, qty, showChain ? o.chainName : '', o.validTo ? `fino al ${formatShortDate(o.validTo)}` : ''].filter(Boolean).map(escapeHtml).join(' · ')}${extra}</span>
      </div>
      <div class="offer-price">
        <span class="price">${formatEuro(o.price)}</span>
        ${o.discountPct ? `<span class="badge-discount">−${o.discountPct}%</span>` : badge ? `<span class="badge-discount is-soft" title="Rispetto al prezzo medio">${badge}</span>` : o.unitPrice ? `<span class="unit-price">${formatUnitPrice(o.unitPrice)}</span>` : ''}
      </div>
      <button class="offer-add-btn" type="button" data-action="add-offer-to-list" data-offer-id="${o.id}" data-store-name="${escapeHtml(storeName || o.chainName || '')}" title="Aggiungi alla lista della spesa">
        ${icon('plus')}<span>Lista</span>
      </button>
    </li>`;
}

// Assegna a ogni alimento della lista il negozio consigliato (con prezzo e scadenza).
function splitByStore() {
  if (!lastReport) return;
  const list = getList(lastReport.listId);
  const { result } = lastReport;
  if (!list || !result.recommended) return;
  const snapshot = list.items.map((i) => ({ ...i }));
  const prevGroupBy = list.groupBy;
  const prevOrder = list.storeOrder;
  const rec = result.recommended;
  result.items.forEach((p, idx) => {
    const a = rec.assignment[idx];
    const item = list.items.find((i) => i === p.item);
    if (!item) return;
    if (a) {
      item.store = {
        chain: a.chain,
        chainName: a.offer.chainName,
        offerId: a.offer.id,
        product: [a.offer.brand, a.offer.name].filter(Boolean).join(' '),
        price: Math.round(a.cost * 100) / 100,
        unitPrice: a.offer.unitPrice ? formatUnitPrice(a.offer.unitPrice) : '',
        validTo: a.offer.validTo,
      };
    } else {
      delete item.store;
    }
  });
  list.groupBy = 'store';
  list.storeOrder = rec.chains;
  persistList(list);
  navigate('detail', { listId: list.id });
  showToast('Lista divisa per negozio', {
    actionLabel: 'Annulla',
    onAction: () => {
      list.items = snapshot;
      list.groupBy = prevGroupBy;
      list.storeOrder = prevOrder;
      persistList(list);
      render();
    },
  });
}

function toggleGroupBy() {
  const list = getSelectedList();
  if (!list) return;
  list.groupBy = list.groupBy === 'store' ? 'category' : 'store';
  persistList(list);
  closeAllSheets(() => render());
}

async function searchPlace() {
  const input = $('placeInput');
  try {
    const hit = await geocode(input.value);
    await setPlace({ ...hit, radiusKm: offersState.draftRadius });
  } catch (err) {
    showToast(err.message);
  }
}

async function useMyPosition() {
  try {
    const hit = await currentPosition();
    $('placeInput').value = '';
    await setPlace({ ...hit, radiusKm: offersState.draftRadius });
  } catch (err) {
    showToast(err.message);
  }
}

async function setPlace(place) {
  offersState.place = place;
  setSetting('offersPlace', place);
  closeAllSheets(() => refreshOffers());
}

function openPlaceSheet() {
  offersState.draftRadius = offersState.place ? offersState.place.radiusKm : 1;
  $('placeInput').value = offersState.place && offersState.place.label !== 'La mia posizione' ? offersState.place.label : '';
  renderRadiusPicker();
  openSheet('place');
}

function renderRadiusPicker() {
  const currentRadius = offersState.draftRadius ?? (offersState.place ? offersState.place.radiusKm : 1);
  document.querySelectorAll('#radiusPicker .preset').forEach((b) => {
    const on = Number(b.dataset.km) === currentRadius;
    b.classList.toggle('selected', on);
    b.setAttribute('aria-checked', String(on));
  });
  const activeRadius = offersState.place ? offersState.place.radiusKm : currentRadius;
  document.querySelectorAll('#quickRadiusBar .preset-pill').forEach((b) => {
    const on = Number(b.dataset.km) === activeRadius;
    b.classList.toggle('active', on);
    b.classList.toggle('selected', on);
    b.setAttribute('aria-checked', String(on));
  });
}

// ---------- EVENTI (un solo gestore delegato per tutta l'app) ----------

const actions = {
  'go-tab': (b) => navigate(b.dataset.view),
  back: () => goBack(),
  'new-list': () => newList(),
  'open-list': (b) => navigate('detail', { listId: Number(b.dataset.listId) }),
  'reuse-list': (b) => restoreArchivedList(Number(b.dataset.listId)),
  'restore-list': (b) => restoreArchivedList(Number(b.dataset.listId)),
  'close-list': () => closeAllSheets(archiveList),
  'delete-archived': (b) => deleteArchived(Number(b.dataset.listId)),
  'open-target-list': () => selectedListId && navigate('detail', { listId: selectedListId }),

  'open-sheet': (b) => {
    if (b.dataset.sheet === 'categoryOrder') openCategoryOrder();
    else openSheet(b.dataset.sheet);
    if (b.dataset.sheet === 'appMenu') prepareBackup().catch(() => {});
    if (b.dataset.sheet === 'listMenu') {
      const list = getSelectedList();
      const hasStore = list && list.items.some((i) => i.store);
      const mi = $('groupByMenuItem');
      mi.classList.toggle('hidden', !hasStore);
      mi.querySelector('span').textContent = list && list.groupBy === 'store' ? 'Raggruppa per reparto' : 'Raggruppa per negozio';
    }
  },
  'close-sheet': () => closeTopSheet(),
  'confirm-ok': () => {
    const cb = confirmCallback;
    confirmCallback = null;
    closeAllSheets(() => cb && cb());
  },

  'toggle-check': (b) => toggleCheck(Number(b.dataset.foodId)),
  'edit-item': (b) => openItemEdit(Number(b.dataset.foodId)),
  'open-quick-add': () => openQuickAdd(),
  'toggle-shopping': () => setShoppingMode(!shoppingMode),
  'rename-list': () => focusTitleEnd(),

  'open-photo': () => openPhoto(),
  'photo-download': () => downloadPhoto(),
  'photo-share': () => sharePhoto(),
  'share-text': () => shareListText('share'),
  'copy-text': () => shareListText('copy'),
  'uncheck-all': () => closeAllSheets(uncheckAll),
  'duplicate-list': () => closeAllSheets(() => copyListToNew(selectedListId)),
  'archive-list': () => closeAllSheets(archiveList),
  'delete-list': () => deleteSelectedList(),

  'toggle-food': (b) => toggleFoodFromPicker(Number(b.dataset.foodId), b.closest('[data-picker]').dataset.picker),
  'create-from-search': (b) => createFromSearch(b.closest('[data-picker]').dataset.picker),
  'toggle-category': (b) => {
    const id = b.dataset.categoryId;
    const group = b.closest('.picker-group');
    const collapsed = !collapsedCategories.has(id);
    if (collapsed) collapsedCategories.add(id);
    else collapsedCategories.delete(id);
    group.classList.toggle('collapsed', collapsed);
    b.setAttribute('aria-expanded', String(!collapsed));
  },
  'jump-category': (b) => jumpToCategory(b.closest('[data-picker]'), b.dataset.categoryId),
  'edit-food': (b) => openFoodSheet(Number(b.dataset.foodId)),
  'new-food': () => openFoodSheet(null, route.view === 'catalog' ? catalogQuery.trim() : ''),
  'pick-icon': (b) => {
    foodSheetIcon = b.dataset.iconName;
    el.iconPicker.querySelectorAll('.icon-choice').forEach((c) => {
      const on = c === b;
      c.classList.toggle('selected', on);
      c.setAttribute('aria-checked', String(on));
    });
  },
  'save-food': () => saveFoodSheet(),
  'delete-food': () => deleteFoodFromSheet(),

  'qty-step': (b) => stepQty(Number(b.dataset.dir)),
  'qty-preset': (b) => (el.qtyInput.value = b.dataset.qty),
  'remove-edit-item': () => removeEditingItem(),
  'remove-item-store': () => {
    const item = getSelectedList()?.items.find((i) => i.foodId === editingFoodId);
    if (item) {
      delete item.store;
      delete item.fromOffer;
    }
    $('itemStoreRow').classList.add('hidden');
  },

  'open-place': () => openPlaceSheet(),
  'place-search': () => searchPlace(),
  'place-geo': () => useMyPosition(),
  'place-radius': (b) => {
    offersState.draftRadius = Number(b.dataset.km);
    renderRadiusPicker();
  },
  'set-radius': async (b) => {
    const km = Number(b.dataset.km);
    if (!offersState.place) {
      offersState.draftRadius = km;
      openPlaceSheet();
      return;
    }
    offersState.place.radiusKm = km;
    offersState.draftRadius = km;
    await setSetting('offersPlace', offersState.place);
    renderRadiusPicker();
    refreshOffers();
  },
  'toggle-store': (b) => {
    offersState.hasUserToggled = true;
    const storeId = b.dataset.storeId;
    if (offersState.expandedStores.has(storeId)) {
      offersState.expandedStores.delete(storeId);
    } else {
      offersState.expandedStores.add(storeId);
    }
    renderOffers();
  },
  'expand-store-all': (b) => {
    offersState.expandedAllStores.add(b.dataset.storeId);
    renderOffers();
  },
  'add-offer-to-list': async (b) => {
    const offerId = b.dataset.offerId;
    const storeName = b.dataset.storeName || '';
    const all = activeOffers(offersState.data?.offers || []);
    const offer = all.find((o) => o.id === offerId);
    if (!offer) return;
    await addOfferToList(offer, storeName);
  },
  'choose-target-list': async (b) => {
    if (!pendingOfferToAdd) {
      closeTopSheet();
      return;
    }
    const listId = b.dataset.listId;
    const { offer, storeName } = pendingOfferToAdd;
    pendingOfferToAdd = null;
    closeTopSheet();

    let targetList;
    if (listId === 'new') {
      targetList = await createList();
    } else {
      targetList = getList(Number(listId));
    }
    if (targetList) {
      await addOfferToSpecificList(offer, storeName, targetList);
    }
  },
  'offers-filter-cat': (b) => {
    offersState.selectedCategory = b.dataset.categoryId || null;
    renderOffers();
  },
  'clear-offers-search': () => {
    offersState.offersFilter = '';
    renderOffers();
  },
  'offers-retry': () => refreshOffers(),
  'jump-chain': (b) => {
    const target = document.getElementById('chain-' + b.dataset.chain);
    if (target) target.scrollIntoView({ behavior: reducedMotion.matches ? 'auto' : 'smooth', block: 'start' });
  },
  'split-by-store': () => splitByStore(),
  'toggle-group-by': () => toggleGroupBy(),
  'open-list-offers': () => {
    closeAllSheets(() => navigate('offers'));
  },

  'open-category-order': () => openCategoryOrder(),
  'move-category': (b) => moveCategory(b.dataset.categoryId, Number(b.dataset.dir)),
  'reset-category-order': () => saveCategoryOrder(CATEGORIES.map((c) => c.id)),

  'export-backup': () => exportBackup(),
  'import-backup': () => el.importFile.click(),
};

document.addEventListener('click', (e) => {
  if (Date.now() < suppressClickUntil && e.target.closest('.item')) {
    e.preventDefault();
    return;
  }
  const target = e.target.closest('[data-action]');
  if (!target || target.disabled) return;
  // mentre uno sheet si sta chiudendo (in attesa del popstate) si ignorano i tocchi ripetuti
  if (pendingPop) {
    e.preventDefault();
    return;
  }
  const handler = actions[target.dataset.action];
  if (!handler) return;
  e.preventDefault();
  handler(target, e);
});

// Card e righe con role="link": Invio/Spazio come il click.
document.addEventListener('keydown', (e) => {
  if ((e.key === 'Enter' || e.key === ' ') && e.target.matches('[role="link"][data-action]')) {
    e.preventDefault();
    e.target.click();
  }
});

// Pressione prolungata su una riga della lista = quantità e nota.
let longPress = null;
el.detailItems.addEventListener('pointerdown', (e) => {
  const btn = e.target.closest('.item-check');
  if (!btn) return;
  const { clientX: x, clientY: y } = e;
  clearTimeout(longPress?.timer);
  longPress = {
    x,
    y,
    timer: setTimeout(() => {
      suppressClickUntil = Date.now() + 500;
      if (swipe && swipe.horizontal) swipe.row.style.transform = '';
      swipe = null; // il gesto ora appartiene allo sheet: niente swipe-per-togliere
      haptic(15);
      openItemEdit(Number(btn.dataset.foodId));
    }, 520),
  };
});
['pointerup', 'pointercancel', 'pointerleave'].forEach((t) =>
  el.detailItems.addEventListener(t, () => clearTimeout(longPress?.timer))
);
el.detailItems.addEventListener('pointermove', (e) => {
  if (longPress && Math.hypot(e.clientX - longPress.x, e.clientY - longPress.y) > 8) clearTimeout(longPress.timer);
});
el.detailItems.addEventListener('contextmenu', (e) => {
  if (e.target.closest('.item-check')) e.preventDefault();
});

el.detailTitle.addEventListener('blur', () => renameSelectedList(el.detailTitle.textContent));
el.detailTitle.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    el.detailTitle.blur();
  } else if (e.key === 'Escape') {
    el.detailTitle.textContent = getSelectedList()?.name || '';
    el.detailTitle.blur();
  }
});
el.detailTitle.addEventListener('paste', (e) => {
  e.preventDefault();
  document.execCommand('insertText', false, (e.clipboardData.getData('text/plain') || '').replace(/\s+/g, ' '));
});

el.catalogSearch.addEventListener('input', () => {
  catalogQuery = el.catalogSearch.value;
  renderCatalog();
});
el.quickAddSearch.addEventListener('input', () => {
  quickAddQuery = el.quickAddSearch.value;
  renderQuickAdd();
});
// Invio nella ricerca: aggiunge l'unico risultato o crea l'alimento.
[el.catalogSearch, el.quickAddSearch].forEach((input) => {
  input.addEventListener('keydown', (e) => {
    if (e.key !== 'Enter') return;
    e.preventDefault();
    const picker = input === el.catalogSearch ? el.catalogPicker : el.quickAddPicker;
    const chips = picker.querySelectorAll('.picker-group:not(.picker-frequent) .chip-main');
    const create = picker.querySelector('.create-row');
    if (chips.length === 1 && !chips[0].closest('.chip').classList.contains('selected')) chips[0].click();
    else if (create && chips.length === 0) create.click();
    else input.blur();
  });
});

document.getElementById('offersBody').addEventListener('change', (e) => {
  if (e.target.matches('[data-role="report-list"]')) {
    offersState.listId = Number(e.target.value);
    render();
  }
});

document.getElementById('placeForm').addEventListener('submit', (e) => {
  e.preventDefault();
  searchPlace();
});

el.targetListSelect.addEventListener('change', () => {
  selectedListId = Number(el.targetListSelect.value) || null;
  render();
});

el.foodCategory.addEventListener('change', renderIconPicker);
el.foodName.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    saveFoodSheet();
  }
});
el.noteInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    e.preventDefault();
    closeTopSheet();
  }
});

document.addEventListener('input', (e) => {
  if (e.target.id === 'offersSearchInput') {
    offersState.offersFilter = e.target.value;
    updateStoreCardsOnly();
  }
});

// Nascondi le voci che il browser non supporta.
if (!navigator.share) document.querySelectorAll('[data-requires="share"]').forEach((n) => n.classList.add('hidden'));

// ---------- INIT ----------

async function loadData() {
  foods = await syncSeedFoods(FOODS, SEED_VERSION);
  await migrateFoodIcons();
  rebuildFoodIndexes();
  lists = await getLists();
  lists.forEach((l) => (l.items = l.items.filter((i) => foodsById.has(i.foodId))));
  const savedOrder = await getSetting('categoryOrder', null);
  categoryOrder = Array.isArray(savedOrder) ? savedOrder : CATEGORIES.map((c) => c.id);
  const al = activeLists();
  selectedListId = al.length ? al[0].id : null;
  offersState.place = await getSetting('offersPlace', null);
}

async function init() {
  hydrateIcons();
  await initDB();
  await loadData();
  history.replaceState({ fromApp: false }, '', location.hash || VIEW_HASH.lists);
  applyRoute(parseHash(location.hash));
  requestAnimationFrame(() => document.body.classList.add('ready'));
}

init();

